local class = require(script.Parent.Parent.apis.class)
local BaseComponent = require(script.Parent.Parent.apis.BaseComponent)
local module = class(script.Name, BaseComponent, require(script.Parent.Text))

function module:ctor(element)
    self.super.ctor(self, element)
end

function module:BindText(...)
    local args = {...}
    table.insert(args, 2, "Text")
    return self:Bind(table.unpack(args))
end

return module